<section class="panel" id="sefaz-status"><h2>SEFAZ — Homologação</h2><p id="sefaz-summary" class="muted">Carregando estado da comunicação...</p><details><summary>Detalhes</summary><pre id="sefaz-details">Ainda não testado.</pre></details><button type="button" class="btn" id="sefaz-test" disabled>Testar comunicação SEFAZ</button><p class="muted">Executa somente NFeStatusServico4. Nenhuma NF-e será transmitida.</p></section>
<section class="panel" id="ready"><h2>Prontidão</h2><p>Produção: <strong>Bloqueada</strong>. Configuração ausente resulta em <strong>FISCAL_PENDING</strong>.</p></section><script>(()=>{const button=document.querySelector('#sefaz-test'),summary=document.querySelector('#sefaz-summary'),details=document.querySelector('#sefaz-details');const show=data=>{const last=data.last||null;summary.textContent=last?(last.success?'Online':'Indisponível/erro')+' · último teste '+(data.last_at||last.raw_received_at||''):'Não testado';details.textContent=last?['Ambiente: Homologação','UF: '+(last.uf||data.uf||''),'Serviço: '+(last.service||'NFeStatusServico4'),'cStat: '+(last.cStat||'—'),'Motivo: '+(last.xMotivo||last.error_code||'—'),'Data/hora SEFAZ: '+(last.dhRecbto||'—'),'Latência: '+(last.latency_ms??'—')+' ms'].join('\n'):'Ainda não testado.';button.disabled=!data.certificate_ready};fetch('/plataforma/ajax-sefaz-status.php?id=<?= $tenantId ?>').then(r=>r.json()).then(show).catch(()=>summary.textContent='Não foi possível carregar o estado.');button.onclick=async()=>{if(!confirm('Será realizada apenas uma consulta de Status do Serviço em HOMOLOGAÇÃO. Nenhuma NF-e será transmitida.'))return;button.disabled=true;summary.textContent='Testando comunicação segura...';const form=new FormData();form.set('csrf_token','<?=$csrf?>');form.set('environment','2');try{const response=await fetch('/plataforma/ajax-sefaz-status.php?id=<?=$tenantId?>',{method:'POST',body:form,credentials:'same-origin'});const json=await response.json();if(!json.success)throw new Error(json.error_message||json.error_code);const d=json.data;summary.textContent=d.success?'✓ Comunicação estabelecida':'SEFAZ indisponível';details.textContent=['Ambiente: Homologação','UF: '+d.uf,'Serviço: '+d.service,'cStat: '+d.cStat,'Motivo: '+d.xMotivo,'Data/hora SEFAZ: '+(d.dhRecbto||'—'),'Latência: '+d.latency_ms+' ms'].join('\n')}catch(e){summary.textContent=e.message}finally{setTimeout(()=>button.disabled=false,15000)}}})();</script><?php renderPlatformEnd();?>
